//autogenerated routine code, DO NOT TOUCH!
use crate::chassis::Chassis;
use crate::robot::Robot;
use crate::subsystems::*;
use vexide::math::*;
use vexide::prelude::*;
use alloc::rc::Rc;
use core::time::Duration;
use crate::helpers::*;
use crate::motion_control::ramsete::*;
use crate::localization::dsr::Wall;
use futures_util::future::join;
use vexide::smart::motor::BrakeMode;

pub async fn run(robot: &mut Robot) {
	let _log_task = spawn(Chassis::log_pose(Rc::clone(&robot.chassis.pose)));
	// Start
	robot.chassis.set_pose(Pose::new(9.215051002659719, 74.81801875168092, Angle::from_degrees(180.0)));

	// Action 1
	robot.lift.score_height(0, "neutral");
	robot.toggle.auto_toggle_loop(Duration::from_millis(700)).await;
	robot.chassis.distance_reset(&robot.dsrs.right, Wall::Top).await;
	robot.chassis.distance_reset(&robot.dsrs.front, Wall::Left).await;

	// Motion 1
	let mut motion1 = MotionProfile::new("driver_2/motion1.json");
	join(robot.chassis.drive_along(&mut motion1), async {
		sleep(Duration::from_millis(200)).await;
		robot.lift.matchload();
	}).await;

	// Action 2
	robot.chassis.turn(100.0, 30.0, 1000.0).await;

	// Motion 2
	let mut motion2 = MotionProfile::new("driver_2/motion2.json");
	robot.chassis.drive_along(&mut motion2).await;

	// Action 3
	//robot.chassis.swing_turn(100.0, 30.0, 1000.0, "left").await;
	robot.chassis.drive_raw_v(-12.0, -10.0, Duration::from_millis(400)).await;
	robot.lift.claw_close();
	robot.chassis.drive_raw_v(-12.0, -10.0, Duration::from_millis(150)).await;
	robot.chassis.distance_reset(&robot.dsrs.right, Wall::Top).await;
	robot.chassis.distance_reset(&robot.dsrs.back, Wall::Left).await;
	robot.chassis.turn_with_conditions(60.0, 300.0, 50.0, false, 1000.0, "none").await;
	robot.chassis.turn_with_conditions(100.0, 280.0, 35.0, false, 1000.0, "left").await;

	// Motion 3
	let mut motion3 = MotionProfile::new("driver_2/motion3.json");
	join(robot.chassis.drive_along(&mut motion3), async {
		robot.lift.score_height(2, "neutral");
	}).await;

	// Motion 4
	let mut motion4 = MotionProfile::new("driver_2/motion4.json");
	robot.chassis.drive_along(&mut motion4).await;

	// Action 4
	robot.chassis.drive_raw_v(-5.0, -5.0, Duration::from_millis(400)).await;
	robot.lift.drop();

}
